head.script:
scwin.onpageload = function() {
	const tooltip = document.getElementById("mf_tooltip");
	tooltip.style.display = "none";
};

scwin.gridView1_onheaderover = function(info) {
	const tooltip = document.getElementById("mf_tooltip");
	const target = document.getElementById(info.id);
	let _left = target.offsetLeft + "px";
	let _top = target.offsetTop + target.offsetHeight + "px";
	tooltip.style.left = _left;
	tooltip.style.top = _top;	
	tooltip.style.display = "flex";
	tooltip.value =info.id;
};
scwin.gridView1_onheadermouseout = function(info) {
	const tooltip = document.getElementById("mf_tooltip");
	tooltip.value = "";
	tooltip.style.display = "none";
};
scwin.gridView1_onbodymouseover = function(info) {
	//console.log(info);
};

	scwin.fireOver = function(node) {
		if (document.createEventObject) {
			node.fireEvent('onmouseover');
		} else if (document.createEvent) {
			window.evt = document.createEvent('MouseEvents');
			evt.initEvent('mouseover', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.onmouseover == 'function') {
			node.onmouseover();
		}
	}
	scwin.mouseOverBehaviour = function(id) {
		window.el = WebSquare.wUnit.getDomById(id);
		scwin.fireOver(el);
	}	
	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('gridview1').nextElementSibling.style.display == 'flex';
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour('gridview1_column4')");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
